// An app with styles-core.css imports the sources file of each component it uses (dist/sources/<Component>.css,
// generated by scripts/sources.ts from the imports of the component). Every recipe class a case renders must be in
// the files of the components the case uses – otherwise that styling would be silently missing in such an app.
import * as recipes from '@wirecore/wirelayer-recipes';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { componentRecipes, isRecipe, recipeClasses } from '../../../scripts/sources.ts';
import { cases } from './cases.js';
import { renderSettled, type El, type ScopedContent } from './harness.js';

const module = recipes as Record<string, unknown>;
const recipeNames = new Set(Object.keys(module).filter((name) => isRecipe(module[name])));
const classesOf = new Map([...recipeNames].map((name) => [name, recipeClasses(module[name] as never)]));
/** Classes of any recipe – others (Lucide, ProseMirror, pdf.js …) are not WireLayer's to bring along */
const recipeClassSet = new Set([...classesOf.values()].flat());

const packageDir = (name: string) => join(import.meta.dirname, '../..', name);
const manifest = (...packages: string[]) =>
    new Map(packages.flatMap((name) => [...componentRecipes(packageDir(name), recipeNames)]));
// Vue and React render the same DOM (parity.test.ts), so the Vue DOM checks the React files as well
const manifests = { vue: manifest('vue', 'blocks-vue'), react: manifest('react', 'blocks-react') };

const isEl = (value: unknown): value is El =>
    !!value && typeof value === 'object' && 'type' in value && 'props' in value && 'children' in value;

/** Any property of it, at any depth, is again a stand-in (and an empty string where a string is needed) */
const anything: unknown = new Proxy(() => anything, {
    get: (_, key) => (key === Symbol.toPrimitive ? () => '' : anything),
});

const strings = (value: unknown): string[] =>
    typeof value === 'string'
        ? value.split(/\s+/)
        : value && typeof value === 'object'
          ? Object.values(value).flatMap(strings)
          : [];

/** The components of a case and the classes it passes itself (`class`, `classes` and RecipesProvider `recipes`) */
function collect(value: unknown, components: Set<string>, own: Set<string>) {
    if (isEl(value)) {
        if (/^[A-Z]/.test(value.type)) components.add(value.type);
        const { $scoped, ...props } = value.props as {
            $scoped?: Record<string, ScopedContent>;
            [prop: string]: unknown;
        };
        [props.class, props.classes, props.recipes].flatMap(strings).forEach((cls) => own.add(cls));
        // Slot content only names its components when called – with stand-in slot props (item.value, labelId …)
        for (const content of Object.values($scoped ?? {})) collect(content.render(anything as never), components, own);
        collect(Object.values(props), components, own);
        collect(value.children, components, own);
    } else if (Array.isArray(value)) value.forEach((item) => collect(item, components, own));
    else if (value && Object.getPrototypeOf(value) === Object.prototype) collect(Object.values(value), components, own);
}

describe.each(Object.entries(manifests))('the %s sources files contain the rendered classes', (_, files) => {
    it.each(cases)('%s', async (_, node) => {
        const components = new Set<string>();
        const own = new Set<string>();
        collect(node, components, own);
        expect(
            [...components].filter((name) => !files.has(name)),
            'components without a sources file'
        ).toEqual([]);
        const imported = new Set([...components].flatMap((name) => [...files.get(name)!]));
        const allowed = new Set([...imported].flatMap((recipe) => classesOf.get(recipe)!));
        await renderSettled('vue', node);
        // Portals (dialogs, popups) render outside the container
        const rendered = [...document.body.querySelectorAll('[class]')].flatMap((element) =>
            (element.getAttribute('class') ?? '').split(/\s+/)
        );
        const missing = [...new Set(rendered)].filter(
            (cls) => recipeClassSet.has(cls) && !allowed.has(cls) && !own.has(cls)
        );
        // Name the recipes that have the class, to find the import the generator missed
        const from = (cls: string) => [...classesOf].filter(([, list]) => list.includes(cls)).map(([name]) => name);
        expect(missing.map((cls) => `${cls} (${from(cls).join(', ')})`)).toEqual([]);
    });
});
